import { Button } from "@/registry/erbium/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/registry/erbium/ui/empty";
import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerEmpty = () => (
  <Empty className="w-full">
    <EmptyHeader>
      <EmptyMedia variant="icon">
        <Spinner />
      </EmptyMedia>
      <EmptyTitle>Processing your request</EmptyTitle>
      <EmptyDescription>
        Please wait while we process your request. Do not refresh the page.
      </EmptyDescription>
    </EmptyHeader>
    <EmptyContent>
      <Button variant="outline" size="sm">
        Cancel
      </Button>
    </EmptyContent>
  </Empty>
);

export default SpinnerEmpty;

import ExampleSpinnerEmpty from "../examples/spinner-empty";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleSpinnerEmpty />
  </div>
);

export default Example;
